     * A small testable subclass that overrides getOptionValue to return
     * values from a map. Uses protected no-arg constructor of CommandLine.
     */
    private static class TestableCommandLine extends CommandLine {
        private final Map<Option, String> values = new HashMap<>();

        protected TestableCommandLine() {
            super();
        }

        void put(final Option opt, final String value) {
            values.put(opt, value);
        }

        @Override
        public String getOptionValue(final Option option) {
            return values.get(option);
        }
    }

    @Test
    public void testNullOptionReturnsDefaultSupplier() throws Exception {
        final TestableCommandLine cl = new TestableCommandLine();
        final String result = cl.getParsedOptionValue(null, () -> "defaultValue");
        Assertions.assertEquals("defaultValue", result);
    }

    @Test
    public void testOptionWithNullValueReturnsDefaultSupplier() throws Exception {
        final TestableCommandLine cl = new TestableCommandLine();
        final Option opt = new Option("a", true, "desc");
