        cl.put(opt, "123");
        final Integer result = cl.getParsedOptionValue(opt, () -> -1);
        Assertions.assertEquals(Integer.valueOf(123), result);
    }

    @Test
    public void testConverterThrowsCheckedExceptionIsWrappedInParseException() throws Exception {
        final TestableCommandLine cl = new TestableCommandLine();
        final Option opt = new Option("c", true, "checked");
        // set a converter that throws a checked exception
        opt.setConverter(new Converter<Object, Exception>() {
            @Override
            public Object apply(final String string) throws Exception {
                throw new Exception("boom");
            }
        });
        cl.put(opt, "v");
        Assertions.assertThrows(ParseException.class, () -> cl.getParsedOptionValue(opt, () -> "unused"));
    }

    @Test
    public void testConverterThrowsUnsupportedOperationExceptionIsPropagated() throws Exception {
        final TestableCommandLine cl = new TestableCommandLine();
        final Option opt = new Option("u", true, "unsupported");
        // set a converter that throws UnsupportedOperationException (should be propagated)
        opt.setConverter((Converter<Object, RuntimeException>) s -> {
            throw new UnsupportedOperationException("uoe");
        });
        cl.put(opt, "v");
        Assertions.assertThrows(UnsupportedOperationException.class, () -> cl.getParsedOptionValue(opt, () -> "unused"));
