        ctor.setAccessible(true);
        final CommandLine cl = ctor.newInstance(new ArrayList<String>(), new ArrayList<Option>(), null);
        // With null option, getParsedOptionValue should return supplier value (no reliance on getOptionValue)
        final String result = cl.getParsedOptionValue(null, () -> "refDefault");
        Assertions.assertEquals("refDefault", result);
    }
